// The package carries the schema and the standard packs as data (data/, generated by scripts/data.mjs), and the
// resolver takes them as documents, so it runs without this repository's spec/ and packs/ directories.
import { test } from "node:test";
import assert from "node:assert/strict";
import { createSchemaValidator, DEFAULT_PACKS_DIR, DEFAULT_SCHEMA_PATH, loadPacks, resolveService } from "@meantjs/profile";
import { mkdtemp, mkdir, readdir, rm, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { tmpdir } from "node:os";
import path from "node:path";
import { staleData, writeData } from "../scripts/data.mjs";
import schema from "@meantjs/profile/schema.json" with { type: "json" };
import erc20 from "@meantjs/profile/packs/erc20.profile.json" with { type: "json" };
import erc2612 from "@meantjs/profile/packs/erc2612.profile.json" with { type: "json" };
import permit2 from "@meantjs/profile/packs/permit2.profile.json" with { type: "json" };
import icrc1 from "@meantjs/profile/packs/icrc1.profile.json" with { type: "json" };
import icrc2 from "@meantjs/profile/packs/icrc2.profile.json" with { type: "json" };
import { LEDGER_DID, readJson } from "./helpers.mjs";

test("data/ is byte-identical to spec/ and packs/ (run `npm run data -w packages/resolver` after changing them)", async () => {
  assert.deepEqual(await staleData(), []);
});

test("the exported data parses to the repository's schema and packs", async () => {
  assert.deepEqual(schema, await readJson("spec/profile-v0.schema.json"));
  assert.deepEqual(icrc1, await readJson("packs/icrc1.profile.json"));
  assert.deepEqual(icrc2, await readJson("packs/icrc2.profile.json"));
});

test("createSchemaValidator takes the schema document as well as a path", async () => {
  const fromDoc = await createSchemaValidator(schema);
  const fromPath = await createSchemaValidator();
  for (const doc of [icrc1, icrc2, { kind: "pack" }]) assert.equal(fromDoc(doc), fromPath(doc));
  assert.equal(fromDoc({ kind: "pack" }), false);
  await assert.rejects(createSchemaValidator(42), TypeError);
  await assert.rejects(createSchemaValidator(null), TypeError);
});

test("the default schema and packs are the package's own data/, so they work where the package is installed", async () => {
  const pkg = fileURLToPath(new URL("..", import.meta.url));
  for (const p of [DEFAULT_SCHEMA_PATH, DEFAULT_PACKS_DIR]) assert.ok(p.startsWith(path.join(pkg, "data")), p);
  // the standard contract profiles beside them are shipped too, but are not packs
  assert.deepEqual((await loadPacks()).map(({ doc }) => doc), [erc20, erc2612, icrc1, icrc2]);
  assert.equal(permit2.kind, "contract");
});

test("resolveService runs on the shipped data alone", async () => {
  const r = await resolveService({ did: LEDGER_DID, packs: [{ doc: icrc1 }, { doc: icrc2 }], validateSchema: await createSchemaValidator(schema) });
  assert.equal(r.ok, true);
  assert.deepEqual(r.profiles.map((p) => [p.name, p.status]), [["icrc1", "applied"], ["icrc2", "applied"]]);
});

test("regenerating data/ removes the copy of a pack whose source was deleted or renamed", async () => {
  const dir = await mkdtemp(path.join(tmpdir(), "resolver-data-"));
  try {
    const root = path.join(dir, "repo");
    const pkg = path.join(dir, "pkg");
    await mkdir(path.join(root, "spec"), { recursive: true });
    await mkdir(path.join(root, "packs"), { recursive: true });
    await writeFile(path.join(root, "spec/profile-v0.schema.json"), "{}");
    await writeFile(path.join(root, "packs/a.profile.json"), "{}");
    await writeFile(path.join(root, "packs/b.profile.json"), "{}");
    await writeData({ root, pkg });
    await rm(path.join(root, "packs/b.profile.json"));
    assert.deepEqual(await staleData({ root, pkg }), [path.join("data", "packs", "b.profile.json") + " (no source)"]);
    const { removed } = await writeData({ root, pkg });
    assert.deepEqual(removed, [path.join("data", "packs", "b.profile.json")]);
    assert.deepEqual(await readdir(path.join(pkg, "data/packs")), ["a.profile.json"]);
    assert.deepEqual(await staleData({ root, pkg }), []);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});
